const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ 
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  const context = await browser.newContext({
    viewport: { width: 1280, height: 900 },
    locale: 'zh-CN'
  });

  const page = await context.newPage();

  console.log("正在打开网站...");
  await page.goto('https://gez.dongguanbank.cn/landlord/#/house/index', {
    waitUntil: 'networkidle',
    timeout: 30000
  });

  // Wait a bit for the page to fully render
  await page.waitForTimeout(2000);

  console.log("页面标题:", await page.title());

  // Take a screenshot to see the current state
  await page.screenshot({ path: '/tmp/page1.png', fullPage: false });

  // Try to find login form
  // Look for username/password fields
  const pageContent = await page.content();
  console.log("页面包含关键词:", {
    login: pageContent.includes('登录'),
    username: pageContent.includes('账号') || pageContent.includes('用户名') || pageContent.includes('手机'),
    password: pageContent.includes('密码'),
    landlord: pageContent.includes('房东') || pageContent.includes('房源'),
  });

  // Try common login field selectors
  const usernameInputs = await page.locator('input[type="text"], input[placeholder*="账号"], input[placeholder*="手机"], input[placeholder*="用户名"], input[name*="user"], input[name*="account"], input[name*="phone"]').all();
  console.log(`找到 ${usernameInputs.length} 个文本输入框`);

  const passwordInputs = await page.locator('input[type="password"]').all();
  console.log(`找到 ${passwordInputs.length} 个密码输入框`);

  // If we find input fields, fill them
  if (usernameInputs.length > 0) {
    await usernameInputs[0].fill('18122859721');
    console.log("已填写账号");
  }

  if (passwordInputs.length > 0) {
    await passwordInputs[0].fill('100911yzp@');
    console.log("已填写密码");
  }

  // Try to find and click login button
  const loginButtons = await page.locator('button, [type="submit"], .login-btn, .submit-btn, button:has-text("登录"), button:has-text("登 录"), div:has-text("登录") >> nth=0').all();

  if (loginButtons.length > 0) {
    // Find the actual button that says login
    for (const btn of loginButtons) {
      const text = await btn.textContent();
      if (text.includes('登录') || text.includes('登 录')) {
        await btn.click();
        console.log("已点击登录按钮");
        break;
      }
    }
  } else {
    // Try clicking any button/div that might be the login action
    console.log("尝试其他方式查找登录按钮...");
    const allBtns = await page.locator('button').all();
    for (const btn of allBtns) {
      const text = await btn.textContent();
      console.log(`按钮文字: "${text}"`);
    }
  }

  await page.waitForTimeout(3000);
  await page.screenshot({ path: '/tmp/page2.png', fullPage: false });

  // Check if we're now on a different page
  console.log("当前URL:", page.url());

  // Try to navigate to the house page / click 房源
  console.log("尝试点击左侧导航的'房源'...");

  // Look for sidebar navigation
  const sidebarLinks = await page.locator('.sidebar, .menu, .nav, aside, .el-menu, [class*="menu"], [class*="nav"], [class*="sidebar"], [class*="left"]').all();
  console.log(`找到 ${sidebarLinks.length} 个侧边栏/导航元素`);

  // Try to find text that says 房源
  const houseLinks = await page.locator('text=房源').all();
  console.log(`找到 ${houseLinks.length} 个包含"房源"的元素`);

  for (const link of houseLinks) {
    const visible = await link.isVisible();
    console.log(`房源元素可见: ${visible}, 文本: "${await link.textContent()}"`);
  }

  await page.screenshot({ path: '/tmp/page3.png', fullPage: true });

  await browser.close();
  console.log("完成");
})();

const puppeteer = require('puppeteer-core');

(async () => {
  try {
    // Connect to existing Chrome instance
    const browser = await puppeteer.connect({
      browserURL: 'http://127.0.0.1:18789',
      defaultViewport: { width: 1280, height: 900 }
    });

    console.log("成功连接到Chrome浏览器");

    const page = await browser.newPage();

    console.log("正在打开网站...");
    await page.goto('https://gez.dongguanbank.cn/landlord/#/house/index', {
      waitUntil: 'networkidle',
      timeout: 30000
    });

    await page.waitForTimeout(2000);
    console.log("页面标题:", await page.title());
    console.log("当前URL:", page.url());

    // Take screenshot
    await page.screenshot({ path: '/tmp/step1.png', fullPage: false });

    // Check page content
    const html = await page.content();
    console.log("页面长度:", html.length);

    // Look for login elements
    const loginFormInfo = await page.evaluate(() => {
      const inputs = document.querySelectorAll('input');
      const inputInfo = [];
      inputs.forEach((inp, i) => {
        inputInfo.push({
          index: i,
          type: inp.type,
          placeholder: inp.placeholder,
          name: inp.name,
          id: inp.id,
          class: inp.className
        });
      });

      const buttons = document.querySelectorAll('button');
      const btnInfo = [];
      buttons.forEach((btn, i) => {
        btnInfo.push({
          index: i,
          text: btn.textContent.trim().substring(0, 50),
          class: btn.className,
          id: btn.id
        });
      });

      return { inputs: inputInfo, buttons: btnInfo };
    });

    console.log("输入框:", JSON.stringify(loginFormInfo.inputs, null, 2));
    console.log("按钮:", JSON.stringify(loginFormInfo.buttons, null, 2));

    // Try to find and fill login fields
    let filled = false;

    // Try finding inputs by placeholder text
    for (const inp of loginFormInfo.inputs) {
      if (inp.placeholder && (inp.placeholder.includes('账号') || inp.placeholder.includes('手机') || inp.placeholder.includes('用户'))) {
        await page.$eval(`input:nth-child(${inp.index + 1})`, el => el.value = '');
        // Better: use the index
        const elements = await page.$$('input');
        await elements[inp.index].click();
        await elements[inp.index].fill('18122859721');
        console.log(`已填写账号到输入框 ${inp.index}`);
        filled = true;
        break;
      }
    }

    if (!filled) {
      // Try first text/password pair
      const textInputs = await page.$$('input[type="text"], input:not([type="password"]):not([type="hidden"])');
      const passInputs = await page.$$('input[type="password"]');

      if (textInputs.length > 0 && passInputs.length > 0) {
        await textInputs[0].click();
        await textInputs[0].fill('18122859721');
        console.log("已填写账号(方法2)");

        await passInputs[0].click();
        await passInputs[0].fill('100911yzp@');
        console.log("已填写密码(方法2)");
        filled = true;
      }
    }

    // Find and click login button
    for (const btn of loginFormInfo.buttons) {
      if (btn.text.includes('登录') || btn.text.includes('登 录')) {
        const btnEl = (await page.$$('button'))[btn.index];
        await btnEl.click();
        console.log("已点击登录按钮");
        break;
      }
    }

    // Wait for login to complete
    await page.waitForTimeout(5000);

    await page.screenshot({ path: '/tmp/step2.png', fullPage: false });
    console.log("登录后URL:", page.url());

    // Check what's on the page now
    const afterLoginInfo = await page.evaluate(() => {
      const allText = document.body.innerText;
      return {
        text: allText.substring(0, 2000),
        hasHouse: allText.includes('房源'),
        hasRent: allText.includes('租约') || allText.includes('到期'),
        hasContract: allText.includes('合同')
      };
    });

    console.log("登录后页面文本:", afterLoginInfo.text);
    console.log("包含房源:", afterLoginInfo.hasHouse);
    console.log("包含租约到期:", afterLoginInfo.hasRent);

    // Try to find and click "房源" in sidebar
    const houseLink = await page.evaluate(() => {
      const elements = document.querySelectorAll('*');
      for (const el of elements) {
        if (el.textContent && (el.textContent.trim() === '房源' || el.textContent.trim().startsWith('房源'))) {
          return {
            tag: el.tagName,
            text: el.textContent.trim(),
            class: el.className,
            rect: el.getBoundingClientRect()
          };
        }
      }
      return null;
    });

    console.log("房源链接:", JSON.stringify(houseLink));

    // Click on 房源
    if (houseLink) {
      const els = await page.$$('*');
      for (const el of els) {
        const text = await el.evaluate(el => el.textContent.trim());
        if (text === '房源' || text.startsWith('房源')) {
          await el.click();
          console.log("已点击'房源'");
          break;
        }
      }
    }

    await page.waitForTimeout(3000);
    await page.screenshot({ path: '/tmp/step3.png', fullPage: true });

    // Get the full page text to see lease info
    const fullText = await page.evaluate(() => document.body.innerText);
    console.log("=== 完整页面文本 ===");
    console.log(fullText.substring(0, 5000));

    await browser.close();
    console.log("完成");
  } catch (err) {
    console.error("错误:", err.message);
    process.exit(1);
  }
})();

